def option(option_id: str, text: str) -> dict:
    return {"id": option_id, "text": text}


def q(
    question_id: str,
    competency_id: str,
    skill_node_id: str,
    question_type: str,
    cognitive_level: str,
    difficulty: float,
    question_text: str,
    options: list[tuple[str, str]],
    correct_options: list[str],
    explanation: str,
    misconception_tags: list[str] | None = None,
) -> dict:
    return {
        "question_id": question_id,
        "competency_id": competency_id,
        "skill_node_id": skill_node_id,
        "question_type": question_type,
        "cognitive_level": cognitive_level,
        "difficulty": difficulty,
        "question_text": question_text,
        "options": [option(option_id, text) for option_id, text in options],
        "correct_options": correct_options,
        "explanation": explanation,
        "misconception_tags": misconception_tags or [],
    }


